              "speaker": "Peter",
              "text": "Great to see you, Bob. I heard you quit your job as a designer a few months ago. Why did you decide to do that?",
              "ipa": "/great tuː siː juː bob aɪ heard juː quit jɔːr job æz ə designer ə few mʌnθs ago why did juː decide tuː duː ðæt/"
