              "ipa": "/well ˈæk.tʃu.ə.li ðæt wʌz maɪ desired job wen aɪ graduated frʌm ðə university haʊˈev.ər aɪ changed maɪ mind wen aɪ worked full-time æz ə graphic designer last jɪr maɪ abilities simply didn't match ðə job rɪˈkwaɪr.mənts/"
